use acorde_core::{Articulation, PlaybackOptions, to_playback_events};
use acorde_render_svg::{SvgRenderOptions, render_svg};

#[test]
fn musescore_trill_survives_import_render_and_playback_metadata() {
    // Generated by MuseScore 4.7.5 from a self-authored one-note MusicXML score.
    let source = include_bytes!("../../../tests/fixtures/issue_311_musescore_trill.mscz");
    let xml = include_str!("../../../tests/fixtures/issue_311_trill.musicxml");
    let from_xml = acorde_io::parse_musicxml(xml).unwrap();
    assert!(
        from_xml.parts[0].staves[0].measures[0].voices[0][0]
            .articulations
            .contains(&Articulation::Trill)
    );
    let score = acorde_io::parse_mscz(source).unwrap();
    let note = &score.parts[0].staves[0].measures[0].voices[0][0];
    assert!(note.articulations.contains(&Articulation::Trill));
    let events = to_playback_events(&score, &PlaybackOptions::default());
    assert_eq!(events.len(), 1);
    assert!(events[0].articulations.contains(&Articulation::Trill));
    let svg = render_svg(&score, &SvgRenderOptions::default()).unwrap();
    assert!(svg.contains("acorde-trill"));
    let output = acorde_io::serialize_mscz(&score).unwrap();
    let restored = acorde_io::parse_mscz(&output).unwrap();
    assert!(
        restored.parts[0].staves[0].measures[0].voices[0][0]
            .articulations
            .contains(&Articulation::Trill)
    );
}
